import test from'node:test';import assert from'node:assert/strict';import{make,validate,apply}from'./state.js';import{history,transition,undo,portable,parse}from'../creative-kit/state.js';const config={make,validate,apply};
test('one benefit can inform multiple alternatives without losing the original position',()=>{const w=make();const before=structuredClone(w.sides);apply(w,{type:'protect',id:'p2',side:'a'});apply(w,{type:'protect',id:'p3',side:'a'});assert.deepEqual(w.sides,before);assert.ok(w.plans.every(p=>p.protects.includes('a')));});
test('changed positions flag linked alternatives but preserve their reasoning; forks stay independent',()=>{const w=make();const text=w.plans[0].mechanism;apply(w,{type:'edit',collection:'sides',item:'a',field:'benefit',value:'A changed priority'});assert.equal(w.plans[0].stale,true);assert.equal(w.plans[0].mechanism,text);apply(w,{type:'fork',id:'p4',parent:'p1'});apply(w,{type:'edit',collection:'plans',item:'p1',field:'mechanism',value:'Different'});assert.equal(w.plans[3].mechanism,text);});
test('removing selected alternatives repairs selection, Undo and portable import keep the work',()=>{const w=make();apply(w,{type:'select',id:'p1'});let h=history({version:1,activeId:w.id,workspaces:[w]});h=transition(h,{type:'remove',id:'p1'},config);assert.equal(h.present.workspaces[0].selected,null);assert.deepEqual(undo(h).present.workspaces[0],w);assert.deepEqual(parse(portable(w,'disagreement',validate),'disagreement',validate),w);});
